// Group tasks by urgency level and format for Mattermost
const tasks = $input.all();

if (tasks.length === 0) {
  return {
    json: {
      hasTasks: false,
      message: "No tasks due soon"
    }
  };
}

// Group by urgency
const grouped = {};
tasks.forEach(task => {
  const level = task.json.urgency_level || 'due_3_days';
  if (!grouped[level]) {
    grouped[level] = [];
  }
  grouped[level].push(task.json);
});

// Format message
const attachments = [];
const colors = {
  'overdue': '#FF6B6B',
  'due_today': '#FFD93D',
  'due_1_day': '#FFA500',
  'due_3_days': '#4ECDC4'
};

const titles = {
  'overdue': '⚠️ Overdue Tasks',
  'due_today': '📋 Tasks Due Today',
  'due_1_day': '⏰ Tasks Due Tomorrow',
  'due_3_days': '📅 Tasks Due in 3 Days'
};

Object.keys(grouped).forEach(level => {
  const tasksInLevel = grouped[level];
  const fields = tasksInLevel.map(task => ({
    short: true,
    title: task.title || 'Untitled Task',
    value: `@${task.assignee_username || 'unassigned'}\nDue: ${task.due_date || 'N/A'}\nPriority: ${task.priority || 'normal'}`
  }));

  attachments.push({
    color: colors[level] || '#4ECDC4',
    title: titles[level] || `Tasks - ${level}`,
    fields: fields.slice(0, 10), // Limit to 10 tasks per attachment
    footer: `Total: ${tasksInLevel.length} task(s)`,
    ts: Math.floor(Date.now() / 1000)
  });
});

// Determine channel based on urgency
let channel = '#tasks-general';
if (grouped['overdue'] && grouped['overdue'].length > 0) {
  channel = '#tasks-urgent';
} else if (grouped['due_today'] && grouped['due_today'].length > 0) {
  channel = '#tasks-urgent';
}

return {
  json: {
    text: `📋 **Task Reminder**\n\nYou have ${tasks.length} task(s) requiring attention.`,
    channel: channel,
    attachments: attachments,
    totalTasks: tasks.length
  }
};

// Log execution
const data = $input.all()[0].json;

return {
  json: {
    workflow_name: 'task-due-reminder',
    execution_id: $execution.id,
    node_name: 'task-reminder-complete',
    status: 'success',
    total_tasks: data.totalTasks || 0,
    channel: data.channel || '#tasks-general',
    timestamp: new Date().toISOString()
  }
};
